# Simulating the library functions for analysis

def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find minimal edit: (old_sub, new_sub, pos)"""
    # This is a simplified version for our purposes
    # In reality, this would be more complex to determine the minimal change

    # Check if it's insertion
    if len(s_in) < len(s_out):
        # Find where the extra characters are inserted
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        # If we get here, it's appending at the end
        return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in))

    # Check if it's deletion
    elif len(s_in) > len(s_out):
        # Find where characters were deleted
        for i in range(len(s_out)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        # If we get here, it's deleting from the end
        return (s_in[len(s_out):], "", len(s_out))

    # Same length - substitution
    else:
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        return ("", "", -1)  # No change

def propose_rule_candidates(s_in, s_out):
    """Generate candidate rules from a changed pair"""
    # This is a simplified version - in practice this would be more sophisticated
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Simple approach: if it's a single character replacement/insertion
    if len(old_sub) == 1 and len(new_sub) <= 3:
        return [(old_sub, new_sub)]
    elif len(old_sub) == 0 and len(new_sub) <= 3:  # Insertion
        # For insertion, we could match the character before the insertion point
        if pos > 0:
            return [(s_in[pos-1], new_sub)]  # Insert after previous char
        else:
            return [(s_in[pos], new_sub)] if len(s_in) > 0 else [(s_in, new_sub)]
    else:
        # For more complex cases, we might want to match larger patterns
        # But for now, let's keep it simple and return a general rule
        return [(s_in, s_out)]

