    print(f"  {idx}: '{inp}' -> '{outp}'")

print("\nProposed rules:")
rules = []

# Analyze each changed pair
for idx, inp, outp in changed:
    print(f"\nAnalyzing pair {idx}: '{inp}' -> '{outp}'")
    candidates = propose_rule_candidates(inp, outp)
    print(f"  Candidates: {candidates}")

    # For now, let's try the first candidate
    if candidates:
        rule = candidates[0]
        print(f"  Trying rule: {rule}")
        rules.append(rule)

print(f"\nInitial rules: {rules}")

# Test these rules on all inputs
def apply_rules(strings, rules):
    """Apply rules sequentially to strings"""
    results = []
    for s in strings:
        result = s
        for pattern, replacement in rules:
            result = result.replace(pattern, replacement)
        results.append(result)
    return results

